import math
import re
from collections import Counter

# Inline 20-word stopword list
STOPWORDS = frozenset(
    "the a an and or of in to is are was were on at for with by it its as".split()
)

_TOKEN_RE = re.compile(r"[a-z]+")


def tokenize(text):
    """Lowercase and extract alphabetic tokens."""
    return _TOKEN_RE.findall(text.lower())


def compute_tfidf(docs):
    """Compute tf-idf scores for a list of documents (strings or token lists).

    tf(t, d) = count(t, d) / len(d)
    idf(t)   = ln(N / df(t))   (natural log, no smoothing)

    Returns (per_doc_score_dicts, idf_dict).
    """
    token_lists = [tokenize(d) if isinstance(d, str) else list(d) for d in docs]
    n_docs = len(token_lists)

    df = Counter()
    for toks in token_lists:
        for t in set(toks):
            df[t] += 1

    idf = {t: math.log(n_docs / c) for t, c in df.items()}

    scores = []
    for toks in token_lists:
        doc_len = len(toks)
        counts = Counter(toks)
        scores.append(
            {
                t: (n / doc_len) * idf[t]
                for t, n in counts.items()
                if t not in STOPWORDS
            }
        )
    return scores, idf


def top_k(per_doc_scores, k=5):
    """Top-k terms per document by tf-idf, ties broken alphabetically."""
    return [
        sorted(doc.items(), key=lambda kv: (-kv[1], kv[0]))[:k]
        for doc in per_doc_scores
    ]


if __name__ == "__main__":
    from docgen import generate_documents, TOPIC_WORDS

    docs = generate_documents(seed=42)
    scores, idf = compute_tfidf(docs)
    tops = top_k(scores)
    for i, terms in enumerate(tops):
        print(f"doc_{i:02d} (topic={TOPIC_WORDS[i]}): "
              + ", ".join(f"{t}={s:.4f}" for t, s in terms))
