import math
from collections import Counter

import pytest

from docgen import generate_documents, TOPIC_WORDS
from keywords import tokenize, compute_tfidf, top_k, STOPWORDS


@pytest.fixture(scope="module")
def corpus():
    return generate_documents(seed=42)


@pytest.fixture(scope="module")
def scored(corpus):
    scores, idf = compute_tfidf(corpus)
    return scores, idf, top_k(scores)


# ---------------------------------------------------------------- structure

def test_doc_shape_and_planting(corpus):
    assert len(corpus) == 12
    for i, tokens in enumerate(corpus):
        topic = TOPIC_WORDS[i]
        # ~150 tokens
        assert 140 <= len(tokens) <= 160
        # planted 8-12 times in its own document
        assert 8 <= tokens.count(topic) <= 12
        # ... and nowhere else in the corpus
        for j, other in enumerate(corpus):
            if j != i:
                assert other.count(topic) == 0


# ------------------------------------------------------- planted word is #1

def test_planted_topic_ranks_number_one(scored):
    _, _, tops = scored
    for i, terms in enumerate(tops):
        assert len(terms) == 5
        assert terms[0][0] == TOPIC_WORDS[i], (
            f"doc {i}: expected '{TOPIC_WORDS[i]}' at rank 1, got '{terms[0][0]}'"
        )


# ------------------------------------------------- universal term behaviour

def test_universal_term_idf_zero_and_excluded(scored):
    scores, idf, tops = scored
    token_lists = [tokenize(d) if isinstance(d, str) else d for _ in [0]]  # noqa
    # find terms present in every one of the 12 documents
    dfs = Counter()
    for doc in generate_documents(seed=42):
        for t in set(doc):
            dfs[t] += 1
    universal = [t for t, c in dfs.items() if c == 12]
    assert universal, "expected at least one term present in every document"

    top_terms = {t for terms in tops for t, _ in terms}
    for t in universal:
        assert idf[t] == 0.0, f"idf('{t}') should be exactly 0"
        assert t not in top_terms, f"'{t}' must never appear in any top-5"


# ------------------------------------------------------------ non-negativity

def test_scores_non_negative(scored):
    scores, _, _ = scored
    for doc_scores in scores:
        for t, s in doc_scores.items():
            assert s >= 0.0, f"negative tf-idf for '{t}': {s}"


# ---------------------------------------------------------- stopword filter

def test_stopwords_never_in_top5(scored):
    _, _, tops = scored
    top_terms = {t for terms in tops for t, _ in terms}
    assert not (top_terms & STOPWORDS), "stopword leaked into a top-5 list"


# --------------------------------------------- hand-computed tiny 3-doc check

def test_tiny_corpus_exact_values():
    docs = [
        "apple apple banana common",
        "banana cherry common",
        "cherry apple common",
    ]
    scores, idf = compute_tfidf(docs)

    # N = 3; df(apple)=df(banana)=df(cherry)=2 -> idf = ln(3/2); df(common)=3 -> idf = ln(1) = 0
    assert idf["common"] == 0.0
    expected_idf = math.log(1.5)  # hand-checked: ln(3/2) = 0.405465108...

    # d1 = [apple, apple, banana, common], len 4
    # tf(apple,d1)=2/4=0.5   -> 0.5 * 0.405465108 = 0.202733 (6dp)
    # tf(banana,d1)=1/4=0.25 -> 0.25 * 0.405465108 = 0.101366 (6dp)
    # d2 = [banana, cherry, common], len 3
    # tf(cherry,d2)=1/3      -> (1/3) * 0.405465108 = 0.135155 (6dp)
    assert round(idf["apple"], 6) == round(expected_idf, 6)
    assert round(scores[0]["apple"], 6) == 0.202733
    assert round(scores[0]["banana"], 6) == 0.101366
    assert round(scores[1]["cherry"], 6) == 0.135155

    # 'common' scores exactly 0 everywhere and never reaches a top-5
    for doc_scores in scores:
        assert doc_scores["common"] == 0.0
    assert all(t != "common" for terms in top_k(scores) for t, _ in terms)


def test_tiny_corpus_stopword_excluded():
    docs = ["the the the apple", "the banana", "apple banana"]
    scores, _ = compute_tfidf(docs)
    tops = top_k(scores)
    for terms in tops:
        assert all(t not in STOPWORDS for t, _ in terms)


if __name__ == "__main__":
    raise SystemExit("run with: pytest test_tfidf.py -v")
